package com.sumedha.commerce.auth.dto.request;
import jakarta.validation.*; import org.junit.jupiter.api.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class RequestValidationTest { static Validator validator; @BeforeAll static void init(){validator=Validation.buildDefaultValidatorFactory().getValidator();} private static boolean invalid(Object o){return !validator.validate(o).isEmpty();}
 @Test void validatesRegisterRequest(){assertFalse(invalid(new RegisterRequest("person@example.test","SecurePassword123")));assertTrue(invalid(new RegisterRequest(" ","SecurePassword123")));assertTrue(invalid(new RegisterRequest("bad","SecurePassword123")));assertTrue(invalid(new RegisterRequest("a".repeat(315)+"@test.test","SecurePassword123")));assertTrue(invalid(new RegisterRequest("a@b.test"," ")));assertTrue(invalid(new RegisterRequest("a@b.test","Short1")));assertTrue(invalid(new RegisterRequest("a@b.test","a".repeat(129)+"1")));assertTrue(invalid(new RegisterRequest("a@b.test","123456789012")));assertTrue(invalid(new RegisterRequest("a@b.test","abcdefghijklm")));}
 @Test void validatesLoginAndTokenRequests(){assertFalse(invalid(new LoginRequest("a@b.test","password")));assertTrue(invalid(new LoginRequest(" ","password")));assertTrue(invalid(new LoginRequest("bad","password")));assertTrue(invalid(new LoginRequest("a@b.test"," ")));assertTrue(invalid(new RefreshTokenRequest(" ")));assertTrue(invalid(new LogoutRequest(" ")));}}
